+package com.example.views;
+
+import java.time.Instant;
+
+import com.example.data.Message;
+import com.example.data.MessageService;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.formlayout.FormLayout;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.data.binder.ValueContext;
+import com.vaadin.flow.data.validator.EmailValidator;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final int MAX_MESSAGE_LENGTH = 500;
+
+    private final MessageService messageService;
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<Message> grid = new Grid<>(Message.class, false);
+
+    public ContactView(MessageService messageService) {
+        this.messageService = messageService;
+
+        add(new H1("Contact"));
+        add(new RouterLink("About", AboutView.class));
+
+        FormLayout form = new FormLayout();
+        form.add(name, email, phone, message);
+
+        send.addClickListener(e -> trySend());
+        send.addClickShortcut(Key.ENTER);
+
+        grid.addColumn(Message::name).setHeader("Name");
+        grid.addColumn(Message::email).setHeader("Email");
+        grid.addColumn(Message::phone).setHeader("Phone");
+        grid.addColumn(Message::content).setHeader("Message");
+        refreshGrid();
+
+        name.addValueChangeListener(e -> enableSendOnClientEdit(e.isFromClient()));
+        email.addValueChangeListener(e -> enableSendOnClientEdit(e.isFromClient()));
+        phone.addValueChangeListener(e -> enableSendOnClientEdit(e.isFromClient()));
+        message.addValueChangeListener(e -> enableSendOnClientEdit(e.isFromClient()));
+
+        add(form, send, grid);
+    }
+
+    private void trySend() {
+        name.setInvalid(false);
+        email.setInvalid(false);
+        phone.setInvalid(false);
+        message.setInvalid(false);
+
+        boolean valid = true;
+
+        if (name.getValue().isBlank()) {
+            name.setErrorMessage("Name is required");
+            name.setInvalid(true);
+            valid = false;
+        }
+
+        String emailValue = email.getValue();
+        String phoneValue = phone.getValue();
+        if (!emailValue.isBlank() && new EmailValidator("invalid").apply(emailValue, new ValueContext()).isError()) {
+            email.setErrorMessage("Enter a valid e-mail address");
+            email.setInvalid(true);
+            valid = false;
+        } else if (emailValue.isBlank() && phoneValue.isBlank()) {
+            email.setErrorMessage("Give an e-mail address or a phone number");
+            email.setInvalid(true);
+            valid = false;
+        }
+
+        if (message.getValue().isBlank()) {
+            message.setErrorMessage("Message is required");
+            message.setInvalid(true);
+            valid = false;
+        } else if (message.getValue().length() > MAX_MESSAGE_LENGTH) {
+            message.setErrorMessage("Message must be at most 500 characters");
+            message.setInvalid(true);
+            valid = false;
+        }
+
+        if (!valid) {
+            return;
+        }
+
+        messageService.addMessage(new Message(name.getValue(), emailValue, phoneValue, message.getValue(), Instant.now()));
+
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+
+        refreshGrid();
+
+        Notification.show("Message sent");
+
+        send.setEnabled(false);
+    }
+
+    private void enableSendOnClientEdit(boolean fromClient) {
+        if (fromClient) {
+            send.setEnabled(true);
+        }
+    }
+
+    private void refreshGrid() {
+        grid.setItems(messageService.getMessages());
+    }
+
+    private boolean hasUnsavedInput() {
+        return !name.getValue().isBlank() || !email.getValue().isBlank()
+                || !phone.getValue().isBlank() || !message.getValue().isBlank();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasUnsavedInput()) {
+            return;
+        }
+
+        var action = event.postpone();
+
+        Dialog dialog = new Dialog();
+        dialog.setHeaderTitle("Discard unsaved message?");
+        dialog.add("You have started writing a message. Leaving now will discard it.");
+
+        Button keepEditing = new Button("Keep editing", e -> dialog.close());
+        Button discard = new Button("Discard", e -> {
+            dialog.close();
+            action.proceed();
+        });
+        dialog.getFooter().add(keepEditing, discard);
+        dialog.open();
+    }
+}
