+package com.example;
+
+import com.example.views.AboutView;
+import com.example.views.ContactView;
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+@SpringBootTest
+class ContactFormTest extends SpringBrowserlessTest {
+
+    @Test
+    void contactViewHasHeadingLinkAndForm() {
+        ContactView view = navigate(ContactView.class);
+
+        assertEquals("Contact", find(H1.class).single().getText());
+
+        RouterLink about = find(RouterLink.class).withText("About").single();
+        assertEquals(AboutView.class, test(about).getRoute().orElse(null));
+
+        TextField name = find(TextField.class).withLabel("Name").single();
+        EmailField email = find(EmailField.class).withLabel("Email").single();
+        TextField phone = find(TextField.class).withLabel("Phone").single();
+        TextArea message = find(TextArea.class).withLabel("Message").single();
+        Button send = find(Button.class).withText("Send").single();
+
+        assertTrue(name.getValue().isEmpty());
+        assertTrue(email.getValue().isEmpty());
+        assertTrue(phone.getValue().isEmpty());
+        assertTrue(message.getValue().isEmpty());
+        assertTrue(send.isEnabled());
+    }
+
+    @Test
+    void aboutViewHasHeading() {
+        navigate(AboutView.class);
+        assertEquals("About", find(H1.class).single().getText());
+    }
+
+    @Test
+    void emptyFormValidationMarksAllFields() {
+        navigate(ContactView.class);
+        int before = gridSize();
+        Button send = find(Button.class).withText("Send").single();
+        test(send).click();
+
+        TextField name = find(TextField.class).withLabel("Name").single();
+        EmailField email = find(EmailField.class).withLabel("Email").single();
+        TextArea message = find(TextArea.class).withLabel("Message").single();
+
+        assertTrue(name.isInvalid());
+        assertEquals("Name is required", name.getErrorMessage());
+
+        assertTrue(email.isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email.getErrorMessage());
+
+        assertTrue(message.isInvalid());
+        assertEquals("Message is required", message.getErrorMessage());
+
+        // nothing sent
+        assertEquals(before, gridSize());
+    }
+
+    private int gridSize() {
+        Grid<?> grid = find(Grid.class).single();
+        return test(grid).size();
+    }
+
+    @Test
+    void invalidEmailIsRejected() {
+        navigate(ContactView.class);
+        TextField name = find(TextField.class).withLabel("Name").single();
+        EmailField email = find(EmailField.class).withLabel("Email").single();
+        TextArea message = find(TextArea.class).withLabel("Message").single();
+        Button send = find(Button.class).withText("Send").single();
+
+        test(name).setValue("Ada");
+        test(email).setValue("not-an-email");
+        test(message).setValue("Hello there");
+
+        test(send).click();
+
+        assertTrue(email.isInvalid());
+        assertEquals("Enter a valid e-mail address", email.getErrorMessage());
+    }
+
+    @Test
+    void phoneAloneIsEnoughToPassValidation() {
+        navigate(ContactView.class);
+        TextField name = find(TextField.class).withLabel("Name").single();
+        TextField phone = find(TextField.class).withLabel("Phone").single();
+        TextArea message = find(TextArea.class).withLabel("Message").single();
+        Button send = find(Button.class).withText("Send").single();
+
+        test(name).setValue("Ada");
+        test(phone).setValue("123456");
+        test(message).setValue("Hello there");
+
+        test(send).click();
+
+        EmailField email = find(EmailField.class).withLabel("Email").single();
+        assertFalse(email.isInvalid());
+    }
+
+    @Test
+    void messageTooLongIsRejected() {
+        navigate(ContactView.class);
+        TextField name = find(TextField.class).withLabel("Name").single();
+        TextField phone = find(TextField.class).withLabel("Phone").single();
+        TextArea message = find(TextArea.class).withLabel("Message").single();
+        Button send = find(Button.class).withText("Send").single();
+
+        test(name).setValue("Ada");
+        test(phone).setValue("123456");
+        test(message).setValue("x".repeat(501));
+
+        test(send).click();
+
+        assertTrue(message.isInvalid());
+        assertEquals("Message must be at most 500 characters", message.getErrorMessage());
+    }
+
+    @Test
+    void successfulSendClearsFormShowsNotificationAndAddsRow() {
+        navigate(ContactView.class);
+        TextField name = find(TextField.class).withLabel("Name").single();
+        EmailField email = find(EmailField.class).withLabel("Email").single();
+        TextField phone = find(TextField.class).withLabel("Phone").single();
+        TextArea message = find(TextArea.class).withLabel("Message").single();
+        Button send = find(Button.class).withText("Send").single();
+
+        test(name).setValue("Ada Lovelace");
+        test(email).setValue("ada@example.com");
+        test(message).setValue("Hello there");
+
+        int before = gridSize();
+
+        test(send).click();
+
+        Notification notification = find(Notification.class).single();
+        assertTrue(test(notification).getText().contains("Message sent"));
+
+        assertTrue(name.getValue().isEmpty());
+        assertTrue(email.getValue().isEmpty());
+        assertTrue(phone.getValue().isEmpty());
+        assertTrue(message.getValue().isEmpty());
+
+        assertFalse(send.isEnabled());
+
+        Grid<?> grid = find(Grid.class).single();
+        assertEquals(before + 1, test(grid).size());
+
+        // editing again re-enables Send
+        test(name).setValue("B");
+        assertTrue(send.isEnabled());
+    }
+
+    @Test
+    void sendingWithEnterKeyWorks() {
+        navigate(ContactView.class);
+        TextField name = find(TextField.class).withLabel("Name").single();
+        EmailField email = find(EmailField.class).withLabel("Email").single();
+        TextArea message = find(TextArea.class).withLabel("Message").single();
+
+        test(name).setValue("Grace Hopper");
+        test(email).setValue("grace@example.com");
+        test(message).setValue("Hi");
+
+        fireShortcut(Key.ENTER);
+
+        Notification notification = find(Notification.class).single();
+        assertTrue(test(notification).getText().contains("Message sent"));
+    }
+
+    @Test
+    void messagesPersistAcrossNavigation() {
+        navigate(ContactView.class);
+        TextField name = find(TextField.class).withLabel("Name").single();
+        EmailField email = find(EmailField.class).withLabel("Email").single();
+        TextArea message = find(TextArea.class).withLabel("Message").single();
+        Button send = find(Button.class).withText("Send").single();
+
+        test(name).setValue("Persisted Person");
+        test(email).setValue("p@example.com");
+        test(message).setValue("Persisted message");
+        test(send).click();
+
+        navigate(AboutView.class);
+        ContactView view2 = navigate(ContactView.class);
+
+        Grid<?> grid = find(Grid.class).single();
+        assertTrue(test(grid).size() >= 1);
+    }
+
+    @Test
+    void leavingWithUnsavedInputShowsConfirmationDialog() {
+        navigate(ContactView.class);
+        TextField name = find(TextField.class).withLabel("Name").single();
+        test(name).setValue("Someone typing");
+
+        RouterLink about = find(RouterLink.class).withText("About").single();
+        test(about).click();
+
+        // Should still be on contact view, dialog shown
+        Dialog dialog = find(Dialog.class).single();
+        assertTrue(test(dialog).isUsable());
+        assertEquals("Contact", find(H1.class).single().getText());
+
+        Button keepEditing = find(Button.class).withText("Keep editing").single();
+        test(keepEditing).click();
+
+        assertEquals("Someone typing", name.getValue());
+        assertEquals("Contact", find(H1.class).single().getText());
+    }
+
+    @Test
+    void discardingNavigatesAway() {
+        navigate(ContactView.class);
+        TextField name = find(TextField.class).withLabel("Name").single();
+        test(name).setValue("Someone typing");
+
+        RouterLink about = find(RouterLink.class).withText("About").single();
+        test(about).click();
+
+        Button discard = find(Button.class).withText("Discard").single();
+        test(discard).click();
+
+        assertEquals("About", find(H1.class).single().getText());
+    }
+
+    @Test
+    void emptyFormNavigatesAwayWithoutDialog() {
+        navigate(ContactView.class);
+        RouterLink about = find(RouterLink.class).withText("About").single();
+        test(about).click();
+
+        assertEquals("About", find(H1.class).single().getText());
+    }
+}
